//! `pyjson` against `agent-rs/fixtures/pyjson.json` (generated by CPython).

use std::sync::OnceLock;

use super::*;
use crate::fixture::{Field, hex_bytes, load};

static FIXTURE: OnceLock<PyJson> = OnceLock::new();

fn fixture() -> &'static PyJson {
    FIXTURE.get_or_init(|| load(include_str!("../../../../fixtures/pyjson.json")))
}

fn cases(name: &str) -> &'static [PyJson] {
    fixture().list_field(name)
}

fn bits(hex: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(hex, 16).expect("float bits"))
}

fn dump_opts(name: &str) -> DumpOpts {
    match name {
        "python_default" => DumpOpts::python_default(),
        "bounded_actual" => DumpOpts::bounded_actual(),
        "opsgate_block" => DumpOpts::opsgate_block(),
        "httpx_json" => DumpOpts::httpx_json(),
        other => panic!("unknown dump option set {other}"),
    }
}

/// Compare a `loads` outcome with the Python outcome of one case.
fn check_load(label: &str, case: &PyJson, outcome: Result<PyJson, LoadError>) {
    match case.field("error") {
        PyJson::Null if case.bool_field("lone_surrogate") => {
            assert!(
                matches!(outcome, Err(LoadError::LoneSurrogate { .. })),
                "{label}: lone surrogate must be rejected (D-8), got {outcome:?}"
            );
        }
        PyJson::Null => {
            let value = outcome.unwrap_or_else(|e| panic!("{label}: Python accepts, Rust: {e}"));
            assert_eq!(
                value.to_json_string().unwrap(),
                case.str_field("dumps"),
                "{label}"
            );
        }
        error => {
            let err = match outcome {
                Ok(value) => panic!("{label}: Python rejects, Rust accepts {value:?}"),
                Err(err) => err,
            };
            let class = error.str_field("class");
            assert_eq!(err.python_class(), class, "{label}: {err}");
            if matches!(class, "JSONDecodeError" | "ValueError") {
                assert_eq!(err.to_string(), error.str_field("message"), "{label}");
            }
        }
    }
}

#[test]
fn loads_matches_cpython() {
    for case in cases("loads") {
        let doc = case.str_field("doc");
        let label = format!("loads({:?})", doc.chars().take(60).collect::<String>());
        check_load(&label, case, loads(doc));
    }
}

#[test]
fn loads_bytes_matches_cpython() {
    for case in cases("loads_bytes") {
        let hex = case.str_field("hex");
        check_load(
            &format!("loads_bytes({hex})"),
            case,
            loads_bytes(&hex_bytes(hex)),
        );
    }
}

#[test]
fn value_corpus_has_at_least_300_documents() {
    assert!(cases("values").len() >= 300);
    assert!(cases("loads").len() >= 300);
}

#[test]
fn dumps_truthiness_kind_and_int_match_cpython() {
    for case in cases("values") {
        let doc = case.str_field("doc");
        let value = loads(doc).unwrap_or_else(|e| panic!("{doc}: {e}"));
        assert_eq!(py_truthy(&value), case.bool_field("truthy"), "bool({doc})");
        assert_eq!(json_kind(&value), case.str_field("kind"), "kind({doc})");
        match (py_int_of(&value), case.opt_str("int")) {
            (Ok(number), Some(expected)) => assert_eq!(number.to_string(), expected, "int({doc})"),
            (Err(err), None) => {
                assert_eq!(
                    err.python_class(),
                    case.str_field("int_error"),
                    "int({doc})"
                );
            }
            (outcome, expected) => panic!("int({doc}): {outcome:?} vs {expected:?}"),
        }
        let dumped = case.field("dumps").as_dict().expect("dumps dict");
        for (name, expected) in dumped {
            let outcome = dumps(&value, &dump_opts(name));
            match (outcome, expected.opt_str("ok")) {
                (Ok(text), Some(ok)) => assert_eq!(text, ok, "dumps[{name}]({doc})"),
                (Err(err), None) => assert_eq!(
                    err.to_string(),
                    expected.field("error").str_field("message"),
                    "dumps[{name}]({doc})"
                ),
                (outcome, _) => panic!("dumps[{name}]({doc}): unexpected {outcome:?}"),
            }
        }
    }
}

#[test]
fn rich_comparison_matches_cpython() {
    let ops: Vec<CmpOp> = cases("compare_ops")
        .iter()
        .map(|op| CmpOp::from_symbol(op.as_str().unwrap()).unwrap())
        .collect();
    for case in cases("compare") {
        let (a_doc, b_doc) = (case.str_field("a"), case.str_field("b"));
        let a = loads(a_doc).unwrap();
        let b = loads(b_doc).unwrap();
        for (op, code) in ops.iter().zip(case.str_field("ops").chars()) {
            let got = match py_cmp(*op, &a, &b) {
                Ok(true) => 'T',
                Ok(false) => 'F',
                Err(_) => 'E',
            };
            assert_eq!(got, code, "{a_doc} {} {b_doc}", op.symbol());
        }
    }
}

#[test]
fn float_repr_format_g_and_round_match_cpython() {
    for case in cases("floats") {
        let x = bits(case.str_field("bits"));
        assert_eq!(py_float_repr(x), case.str_field("repr"), "repr({x:e})");
        assert_eq!(py_format_g(x), case.str_field("g"), "format({x:e}, 'g')");
        for digits in 0..=3u32 {
            assert_eq!(
                py_float_repr(py_round(x, digits)),
                case.str_field(&format!("round{digits}")),
                "round({x:e}, {digits})"
            );
        }
    }
}

#[test]
fn float_parsing_matches_cpython() {
    for case in cases("float_parse") {
        let text = case.str_field("text");
        match (py_float(text), case.opt_str("bits")) {
            (Ok(value), Some("nan")) => assert!(value.is_nan(), "float({text:?})"),
            (Ok(value), Some(expected)) => {
                assert_eq!(value.to_bits(), bits(expected).to_bits(), "float({text:?})");
            }
            (Err(err), None) => assert_eq!(
                err.to_string(),
                case.field("error").str_field("message"),
                "float({text:?})"
            ),
            (outcome, expected) => panic!("float({text:?}): {outcome:?} vs {expected:?}"),
        }
    }
}

#[test]
fn int_parsing_matches_cpython() {
    for case in cases("int_parse") {
        let text = case.str_field("text");
        match (py_int(text), case.opt_str("value")) {
            (Ok(value), Some(expected)) => assert_eq!(value.to_string(), expected, "int({text:?})"),
            (Err(err), None) => assert_eq!(
                err.to_string(),
                case.field("error").str_field("message"),
                "int({text:?})"
            ),
            (outcome, expected) => panic!("int({text:?}): {outcome:?} vs {expected:?}"),
        }
    }
}

#[test]
fn string_helpers_match_cpython() {
    for case in cases("str_repr") {
        let text = case.str_field("text");
        assert_eq!(py_str_repr(text), case.str_field("repr"), "repr({text:?})");
        assert_eq!(py_strip(text), case.str_field("strip"), "strip({text:?})");
        assert_eq!(
            char_len(text) as i64,
            case.int_field("len"),
            "len({text:?})"
        );
    }
    for case in cases("bytes_repr") {
        let data = hex_bytes(case.str_field("hex"));
        assert_eq!(py_bytes_repr(&data), case.str_field("repr"));
    }
}

#[test]
fn non_ascii_digits_are_rejected() {
    // D-6: Python accepts these, Rust deliberately does not.
    assert!(py_int("\u{0663}").is_err());
    assert!(py_int("\u{ff11}\u{ff12}").is_err());
    assert!(py_float("\u{0663}.5").is_err());
}

#[test]
fn duplicate_keys_keep_first_position_with_last_value() {
    let value = loads(r#"{"a": 1, "b": 2, "a": 3}"#).unwrap();
    let keys: Vec<&String> = value.as_dict().unwrap().keys().collect();
    assert_eq!(keys, ["a", "b"]);
    assert_eq!(value.get("a"), Some(&PyJson::Int(3)));
}

#[test]
fn integers_are_normalised_to_i64_when_they_fit() {
    assert_eq!(loads("9223372036854775807").unwrap(), PyJson::Int(i64::MAX));
    assert!(matches!(
        loads("9223372036854775808").unwrap(),
        PyJson::BigInt(_)
    ));
    assert_eq!(loads("-0").unwrap(), PyJson::Int(0));
}

#[test]
fn nesting_limit_is_enforced_without_exhausting_the_stack() {
    // Run on a thread with the default 2 MiB stack of spawned threads (and
    // tokio workers): the deepest accepted document must parse, serialise,
    // compare, clone and drop there (a debug build overflows this stack
    // after a few thousand levels of recursion).
    let handle = std::thread::Builder::new()
        .stack_size(2 * 1024 * 1024)
        .spawn(|| {
            let depth = MAX_NESTING_DEPTH;
            let doc = format!("{}{}", "[".repeat(depth), "]".repeat(depth));
            let value = loads(&doc).expect("deepest accepted nesting");
            let text = dumps(&value, &DumpOpts::python_default()).unwrap();
            assert_eq!(text, doc);
            assert_eq!(py_cmp(CmpOp::Eq, &value, &value), Ok(true));
            let copy = value.clone();
            assert!(copy == value);
            drop(copy);
            drop(value);
            let too_deep = format!("{}{}", "[".repeat(depth + 1), "]".repeat(depth + 1));
            assert_eq!(loads(&too_deep), Err(LoadError::TooDeep));
            let dict_doc = format!("{}1{}", r#"{"a":"#.repeat(depth), "}".repeat(depth));
            assert!(loads(&dict_doc).is_ok());
        })
        .unwrap();
    handle.join().expect("no stack overflow");
}

#[test]
fn four_hex_digits_at_the_end_are_an_unterminated_string() {
    // Pinned here instead of in the fixture: CPython 3.13.11 reported an
    // invalid escape, current 3.13 patch releases (3.13.16) do this.
    let err = loads("\"\\u1234").unwrap_err();
    assert_eq!(
        err.to_string(),
        "Unterminated string starting at: line 1 column 1 (char 0)"
    );
    let err = loads("\"\\u123").unwrap_err();
    assert_eq!(
        err.to_string(),
        "Invalid \\uXXXX escape: line 1 column 3 (char 2)"
    );
}

#[test]
fn printable_table_follows_the_oracle_unicode_version() {
    // U+1FAE9 is assigned in Unicode 16 only: CPython 3.13 (Unicode 15.1)
    // escapes it; U+2EBF0 (Unicode 15.1, CJK Extension I) is printable.
    assert_eq!(py_str_repr("\u{1FAE9}"), "'\\U0001fae9'");
    assert_eq!(py_str_repr("\u{2EBF0}"), "'\u{2EBF0}'");
    assert_eq!(py_str_repr(" "), "' '");
}
